int sum(int[] a) {
    int total = 0;
    for (int x : a) {   // runs n times
        total += x;     // one unit of work
    }
    return total;       // O(n)
}

def total(a):
    s = 0
    for x in a:      # runs n times
        s += x       # one unit of work
    return s         # O(n)

