lesson.src:
int max(int[] a) {
    int best = a[0];             // one variable, whatever n is
    for (int x : a)
        if (x > best) best = x;
    return best;                 // O(1) extra space
}

int[] doubled(int[] a) {
    int[] out = new int[a.length];   // grows with n
    for (int i = 0; i < a.length; i++)
        out[i] = a[i] * 2;
    return out;                      // O(n) extra space
}

def count_down(n):
    if n == 0:
        return
    count_down(n - 1)   # n frames alive at once  ->  O(n) space

